using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation.Infrastructure;

/// <summary>
/// Shared fixture that boots the Aspire AppHost and provides an <see cref="IChatClient"/>
/// along with pre-configured evaluators for quality assessment.
/// </summary>
[TestClass]
public sealed class EvaluationFixture
{
    private static DistributedApplicationAsync? s_app;
    private static IChatClient? s_chatClient;

    public static IChatClient ChatClient => s_chatClient
        ?? throw new InvalidOperationException("Fixture not initialized. Ensure [AssemblyInitialize] has run.");

    /// <summary>
    /// Creates the standard set of evaluators used across all evaluation scenarios.
    /// </summary>
    public static IList<IEvaluator> CreateEvaluators() =>
    [
        new CoherenceEvaluator(),
        new RelevanceEvaluator(),
        new FluencyEvaluator(),
        new GroundednessEvaluator(),
    ];

    [AssemblyInitialize]
    public static async Task Initialize(TestContext context)
    {
        var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        s_app = await appHost.BuildAsync();
        await s_app.StartAsync();
        await s_app.ResourceNotificationService.WaitForResourceHealthyAsync("chat");

        s_chatClient = s_app.CreateHttpClient("chat") is { } httpClient
            ? throw new InvalidOperationException("Chat resource does not expose an HTTP endpoint; resolve via DI.")
            : s_app.Services.GetRequiredService<IChatClient>();
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_app is not null)
        {
            await s_app.DisposeAsync();
        }
    }
}

