using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using MyApp.Evaluation.Infrastructure;

namespace MyApp.Evaluation;

[TestClass]
public class ChatQualityTests
{
    [TestMethod]
    public async Task Greeting_IsCoherentAndRelevant()
    {
        // Arrange
        var chatClient = EvaluationFixture.ChatClient;
        var chatConfig = new ChatConfiguration(chatClient);
        var evaluators = EvaluationFixture.CreateEvaluators();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        // Act
        var response = await chatClient.GetResponseAsync(messages);

        // Evaluate
        var result = new EvaluationResult();
        foreach (var evaluator in evaluators)
        {
            var evalResult = await evaluator.EvaluateAsync(messages, response, chatConfig);
            foreach (var metric in evalResult.Metrics)
            {
                result.Metrics.Add(metric);
            }
        }

        // Assert
        AssertAllMetricsPassThreshold(result);
    }

    [TestMethod]
    public async Task FollowUpQuestion_MaintainsContext()
    {
        // Arrange
        var chatClient = EvaluationFixture.ChatClient;
        var chatConfig = new ChatConfiguration(chatClient);
        var evaluators = EvaluationFixture.CreateEvaluators();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act - first turn
        var response1 = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response1.Messages);

        // Act - follow-up turn
        messages.Add(new ChatMessage(ChatRole.User, "What is its population?"));
        var response2 = await chatClient.GetResponseAsync(messages);

        // Evaluate the multi-turn conversation
        var result = new EvaluationResult();
        foreach (var evaluator in evaluators)
        {
            var evalResult = await evaluator.EvaluateAsync(messages, response2, chatConfig);
            foreach (var metric in evalResult.Metrics)
            {
                result.Metrics.Add(metric);
            }
        }

        // Assert - the response should reference Paris (context maintained)
        var responseText = response2.Text ?? string.Empty;
        Assert.IsTrue(
            responseText.Contains("Paris", StringComparison.OrdinalIgnoreCase)
            || responseText.Contains("million", StringComparison.OrdinalIgnoreCase),
            "Follow-up response should maintain conversational context.");

        AssertAllMetricsPassThreshold(result);
    }

    [TestMethod]
    public async Task InstructionFollowing_RespondsInRequestedFormat()
    {
        // Arrange
        var chatClient = EvaluationFixture.ChatClient;
        var chatConfig = new ChatConfiguration(chatClient);
        var evaluators = EvaluationFixture.CreateEvaluators();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "List exactly 3 benefits of exercise. Use a numbered list.")
        };

        // Act
        var response = await chatClient.GetResponseAsync(messages);

        // Evaluate
        var result = new EvaluationResult();
        foreach (var evaluator in evaluators)
        {
            var evalResult = await evaluator.EvaluateAsync(messages, response, chatConfig);
            foreach (var metric in evalResult.Metrics)
            {
                result.Metrics.Add(metric);
            }
        }

        // Assert - verify numbered list format
        var text = response.Text ?? string.Empty;
        Assert.IsTrue(
            text.Contains("1.") || text.Contains("1)"),
            "Response should contain a numbered list.");

        AssertAllMetricsPassThreshold(result);
    }

    private static void AssertAllMetricsPassThreshold(EvaluationResult result, int threshold = 3)
    {
        foreach (var metric in result.Metrics)
        {
            if (metric.Rating is { } rating)
            {
                Assert.IsTrue(
                    rating.Value >= threshold,
                    $"Metric '{metric.Name}' scored {rating.Value}, below threshold of {threshold}.");
            }
        }
    }
}

